const cmds=[
"find . -name AGENTS.md -print",
"git status --short",
"find . -maxdepth 2 -type d -print | head -100",
"git grep -n -i -E '(:buffer\\b|\\bbuffer\\b|:tab-select\\b)' -- ':!*.py' ':!*.lock' ':!*.mo' | head -250"
]; const r=await Promise.allSettled(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/app",yield_time_ms:10000,max_output_tokens:12000}))); r.forEach((x,i)=>text(JSON.stringify({cmd:cmds[i],result:x.status==="fulfilled"?x.value.output:x.reason})));

